import type { SpotifyPlaylist } from "@/types/spotify.js";

// Playlists generated by Spotify (Daily Mix, radios, Discover Weekly, Release Radar...) change often
const GENERATED_ID_PREFIXES = ["37i9dQZF1E", "37i9dQZEVX"];
// Whole words only: "Remix" or "Mixtape" are regular playlists
const DYNAMIC_NAME = /\b(mix|radio)\b/i;

export function isDynamicPlaylist(playlist: Pick<SpotifyPlaylist, "id" | "name">): boolean {
	return GENERATED_ID_PREFIXES.some((prefix) => playlist.id.startsWith(prefix)) || DYNAMIC_NAME.test(playlist.name ?? "");
}
